from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [any(v != bg for v in row) for row in grid]
    bands = []
    start = None
    for r, flag in enumerate(active + [False]):
        if flag and start is None:
            start = r
        elif not flag and start is not None:
            bands.append((start, r))
            start = None
    candidates = []
    max_shift = min(6, w // 3)
    for i, (a, b) in enumerate(bands):
        for c, d in bands[i+1:]:
            if b-a != d-c:
                continue
            n = b-a
            for src, dst in ((a,c), (c,a)):
                for dx in range(max_shift+1):
                    overlap = total_src = total_dst = missing_count = 0
                    missing = []
                    good_rows = 0
                    for k in range(n):
                        projected = {x+dx for x,v in enumerate(grid[src+k]) if v != bg and x+dx < w}
                        actual = {x for x,v in enumerate(grid[dst+k]) if v != bg}
                        overlap += len(projected & actual)
                        total_src += len(projected)
                        total_dst += len(actual)
                        diff = projected - actual
                        missing_count += len(diff)
                        missing.extend((dst+k,x) for x in diff)
                        if len(projected & actual) >= 2 or (len(projected) == 1 and len(actual & projected)==1):
                            good_rows += 1
                    if total_src == 0 or overlap == 0:
                        continue
                    f1 = 2*overlap / (total_src + total_dst) if total_src + total_dst else 0
                    # Favor the copy that explains several rows, allowing target-only noise at the left edge.
                    score = f1 + 0.015*good_rows/n
                    candidates.append((score, f1, good_rows, missing_count, src, dst, dx, missing))
    if candidates:
        best = max(candidates, key=lambda z:z[0])
        score, f1, good_rows, _, src, dst, dx, missing = best
        n = bands[[a for a,b in bands].index(src)][1]-src if src in [a for a,b in bands] else 0
        if f1 >= 0.55 and good_rows >= max(2, (n+1)//2):
            for r,c in missing:
                last = max((j for j,v in enumerate(grid[r]) if v != bg), default=-1)
                if c > last and out[r][c] == bg:
                    out[r][c] = 1
    return out
